CONT = {}
POI = {}                                   # EN nev -> (magyar nev, extra kereso szavak)


def add(cont, *a):
    a = list(a)
    a.insert(6, [])
    tour(*a); CONT[a[0]] = cont


def Pt(n, hu, kw, la, lo):
    POI[n] = (hu, kw)
    return [n, la, lo]


